export function Lesson({ __rgRoute }: { __rgRoute?: any }) {
  const route = __rgRoute;
  const lessonService = __container.get<LessonService>(LessonService);
  useSyncExternalStore((cb) => lessonService.__subscribe(cb), () => lessonService.__getVersion());
  const [lesson, setLesson] = useState(null);
  const [lessonId, setLessonId] = useState(0);
  const ngOnInit = () => {
    setLesson(lessonService.getById(route.snapshot.params.id));
    setLessonId((lesson === null ? 0 : lesson.id));
  };
  useEffect(() => {
    ngOnInit();
  }, []);
  return (
    <RgSection>
      <RgAppbar title="Rangular Tutorial" titleAlign="center" />
      <RgIconButton name="chevron-left" onPress={() => __router.navigateByUrl("/home")} />
      {lesson && (
        <RgCard>
          <RgText variant="label">Lesson {lesson.id}</RgText>
          <RgText variant="heading">{lesson.title}</RgText>
          <RgText variant="bodyLarge">{lesson.intro}</RgText>
        </RgCard>
      )}
      {!lesson && (
        <RgText variant="bodyLarge">This lesson could not be found.</RgText>
      )}
      {lesson && (
        <RgSection>
          <RgText variant="label">Code</RgText>
          <RgCode>{lesson.code}</RgCode>
        </RgSection>
      )}
      {(lessonId === 2) && (
        <RgCard>
          <RgText variant="label">Live demo: your first component</RgText>
          <Hello />
        </RgCard>
      )}
      {(lessonId === 3) && (
        <RgCard>
          <RgText variant="label">Live demo: interpolation</RgText>
          <InterpolationDemo />
        </RgCard>
      )}
      {(lessonId === 4) && (
        <RgCard>
          <RgText variant="label">Live demo: event binding</RgText>
          <EventsDemo />
        </RgCard>
      )}
      {(lessonId === 5) && (
        <RgCard>
          <RgText variant="label">Live demo: property binding and ngIf</RgText>
          <BindingsDemo />
        </RgCard>
      )}
      {lesson && (
        <RgSection>
          <RgText variant="label">Best practice</RgText>
          <RgText variant="bodyLarge">{lesson.tip}</RgText>
        </RgSection>
      )}
    </RgSection>
  );
}

