export function EventsDemo() {
  const snack = __snackBar;
  const [count, setCount] = useState(0);
  const increment = () => {
    setCount(count + 1);
  };
  const decrement = () => {
    setCount(count - 1);
  };
  const announce = () => {
    snack.open('Button clicked!');
  };
  return (
    <>
      <RgText variant="display">{count}</RgText>
      <RgButton onPress={() => increment()}>Increment</RgButton>
      <RgButton disabled={(count === 0)} onPress={() => decrement()}>Decrement</RgButton>
      <RgButton onPress={() => announce()}>Show a toast</RgButton>
    </>
  );
}

export function BindingsDemo() {
  const [count, setCount] = useState(0);
  const increment = () => {
    setCount(count + 1);
  };
  const reset = () => {
    setCount(0);
  };
  return (
    <>
      <RgText variant="display">{count}</RgText>
      <RgButton onPress={() => increment()}>Increment</RgButton>
      <RgButton disabled={(count === 0)} onPress={() => reset()}>Reset</RgButton>
      {(count >= 5) && (
        <RgText variant="bodyLarge">Past five. Keep going.</RgText>
      )}
      {(count === 0) && (
        <RgText variant="bodyLarge">Reset is disabled while the count is zero. That is property binding at work.</RgText>
      )}
    </>
  );
}

